/**
 * #5412 (cor:acl:140:09, the absent-key form): `memory.read`'s optional `branch` and `automation` change no grammar. An optional
 * parameter with no value has no key, so a grant without either has exactly an S1 grant's terms bytes; a present key is written as
 * any other value. The expected bytes come from `src/lib/grantSignature.optional5412.fixture.json`, generated by
 * `scripts/generate-grant-optional-fixture.py` (Python hashlib), never by the builder under test. The v1 fixtures are untouched.
 */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { GrantTermsError, grantTermsBytes, grantTermsHash, type GrantTerms } from '../grants/terms.js';
import { GRANT_SIGNATURE_PAYLOAD_V1, grantSignaturePayloadBytes } from './grantPayload.js';
import { signatureChallenge } from './payload.js';

interface FixtureTerms {
  appId: string; holder: { kind: GrantTerms['holder']['kind']; id: string }; action: string;
  values: Record<string, unknown>; startsAt: string | null; expiresAt: string | null; maxUses: number | null; reason: string;
}
interface Case {
  name: string; grantId: string; recordVersion: number; requestId: string; terms: FixtureTerms;
  termsUtf8: string; termsHash: string; payloadUtf8: string; canonical: string; challengeHex: string; challengeBase64url: string;
}
const read = (f: string) => readFileSync(new URL(`../${f}`, import.meta.url));
const fixture = JSON.parse(read('grantSignature.optional5412.fixture.json').toString('utf8')) as {
  version: string; termsVersion: string; cases: Case[]; refused: Array<{ name: string; terms: FixtureTerms; refusedBy: 'terms' | 'creation' }>;
};
const sha256hex = (s: string | Buffer) => createHash('sha256').update(s).digest('hex');
const termsOf = (t: FixtureTerms): GrantTerms => ({
  ...t, values: t.values as GrantTerms['values'], startsAt: t.startsAt === null ? null : new Date(t.startsAt), expiresAt: t.expiresAt === null ? null : new Date(t.expiresAt),
});

describe('#5412 absent-key form: the bytes', () => {
  it('names the cases of the pre-build bytes, and the v1 fixtures keep their bytes', () => {
    expect(fixture).toMatchObject({ version: 'hadron-grant-signature-v1', termsVersion: 'hadron-grant-terms-v1' });
    expect(fixture.cases.map((c) => c.name)).toEqual([
      'memory-read-no-optional', 'memory-read-branch', 'memory-read-automation', 'memory-read-branch-and-automation', 'memory-read-org-automation',
    ]);
    expect(fixture.refused.map((c) => c.name)).toEqual([
      'memory-read-branch-null-refused', 'memory-read-branch-empty-refused', 'memory-read-automation-wildcard-refused',
    ]);
    expect(sha256hex(read('grantSignature.fixture.json'))).toBe('6b692a045075b5f773187ce70c70b4ee81e2449ea71f07f7f4b290fc06c42e07');
    expect(sha256hex(read('grantSelectionSignature.fixture.json'))).toBe('af3b32c0022fbd109d259f12aff08dcb19af066a37161eba2fa7165a58896c92');
  });

  it('with no optional key the values line is exactly the S1 line (no null, "", [] or wildcard stands for the absence)', () => {
    const c = fixture.cases[0];
    expect(c.termsUtf8.split('\n')[4]).toBe('values {"memory":"01a2memoryid0000000000000000000a"}');
    expect(fixture.cases[3].termsUtf8.split('\n')[4])
      .toBe('values {"automation":"01a2webhookid000000000000000000w","branch":"docs:api","memory":"01a2memoryid0000000000000000000a"}');
  });

  it.each(fixture.cases.map((c) => [c.name, c] as const))('%s: builder bytes equal the fixture bytes', (_, c) => {
    expect(grantTermsBytes(termsOf(c.terms)).toString('utf8')).toBe(c.termsUtf8);
    expect(grantTermsHash(termsOf(c.terms))).toBe(c.termsHash);
    expect(sha256hex(c.termsUtf8)).toBe(c.termsHash);
    const payload = grantSignaturePayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, { grantId: c.grantId, recordVersion: c.recordVersion, termsHash: c.termsHash, requestId: c.requestId });
    expect(payload.toString('utf8')).toBe(c.payloadUtf8);
    expect(payload.toString('base64')).toBe(c.canonical);
    expect(signatureChallenge(payload).toString('hex')).toBe(c.challengeHex);
    expect(signatureChallenge(payload).toString('base64url')).toBe(c.challengeBase64url);
  });

  it('null and "" have no bytes (the builder refuses them); the wildcard is a terms value, refused for an optional parameter at creation', () => {
    for (const c of fixture.refused) {
      if (c.refusedBy === 'terms') {
        expect(() => grantTermsBytes(termsOf(c.terms))).toThrow(GrantTermsError);
      } else {
        // Pinned at the door in src/lib/grants/memoryReadOptional5412.test.ts; here only that the grammar itself would write it.
        expect(grantTermsBytes(termsOf(c.terms)).toString('utf8')).toContain('"automation":"*"');
      }
    }
  });
});
